mapper.select:
select
   mn.*
from Con_Contract mn
where
1=1

    and mn.con_project_id=#{params.pId}


    and mn.con_project_id=#{params.conProjectId}


    and INSTR(mn.con_name,#{params.conName})


    and INSTR(mn.con_code,#{params.conCode})

and (select count(*) from agreement ar where mn.con_id=ar.con_id and ar.a_relieve=1 and ar.a_is_relieve='01' and ar.state=7) > 0

    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.con_create_time ASC
